    def test_4_post_on_variables_vulnerableToXSS(self):
        
        headers = {}
        headers["content-type"] = "application/json"
        body = " { " + \
            " \"username\" : \"victim\", " + \
            " \"password\" : \"victimpass\" " + \
            " } "
        res_victim = requests \
                .post(self.baseUrlOfSut + "/auth/token", 
                    headers=headers, data=body, allow_redirects=False, verify=False)
        token_victim =  res_victim.json()["access_token"]
        
        auth_victim = "Bearer " + token_victim
        
        # Fault201. Cross-Site Scripting (XSS).
        headers = {}
        headers["Authorization"] = auth_victim # victim
        headers["content-type"] = "application/json"
        body = {}
        body = " { " + \
            " \"key\" : \"<img src=x onerror=alert('XSS')>\", " + \
            " \"value\" : { " + \
            " \"4lVPpeJps\" : \"2HonA0QQM09\", " + \
            " \"UWKyDybWnaD\" : \"eB_e4nRF\" " + \
            " }, " + \
            " \"description\" : \"<img src=x onerror=alert('XSS')>\" " + \
            " } "
        headers['Accept'] = "application/json"
        res_0 = requests \
                .post(self.baseUrlOfSut + "/api/v2/variables",
                    headers=headers, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        location_variables__2 = res_0.headers['location']
        assert is_valid_uri_or_empty(location_variables__2)
        
        assert res_0.status_code == 201
        assert "application/json" in res_0.headers["content-type"]
        assert res_0.json()["key"] == "<img src=x onerror=alert('XSS')>"
        assert res_0.json()["value"] == "{\"4lVPpeJps\": \"2HonA0QQM09\", \"UWKyDybWnaD\": \"eB_e4nRF\"}"
        assert res_0.json()["description"] == "<img src=x onerror=alert('XSS')>"
        assert res_0.json()["is_encrypted"] == True
        assert res_0.json()["team_name"] is None
        
        # Cleanup actions
        headers = {}
        headers["Authorization"] = auth_victim # victim
        headers['Accept'] = "application/json"
        res_1 = requests \
                .delete(resolve_location(location_variables__2, self.baseUrlOfSut + str("/api/v2/variables/4TLslYRwjjymjOg")),
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_1.status_code == 404
        assert "application/json" in res_1.headers["content-type"]
        assert res_1.json()["detail"] == "The Variable with key: `4TLslYRwjjymjOg` was not found"
    
    
